BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L2 — Clearly trivial threshold in practice
(1, 'Misstatements and Control Deficiencies', 'During the audit of Birchwood Distributors, the engagement team sets overall materiality at $200,000 and performance materiality at $150,000. The team identifies an $800 pricing error in office supplies. Under AU-C 450, the auditor should treat this misstatement as:', '["Clearly trivial and not required to be accumulated", "A projected misstatement that must be extrapolated to the population", "A factual misstatement that must be communicated to management", "An immaterial amount that still requires documentation in the summary"]'::jsonb, 0, 'AU-C 450.A2 defines clearly trivial as amounts that are clearly inconsequential, whether taken individually or in the aggregate. An $800 error against $200,000 materiality (0.4%) falls well below any reasonable threshold for accumulation. Unlike immaterial misstatements that must still be accumulated, clearly trivial items need not be accumulated at all.', 'medium', 2),

-- Q2: medium / L2 — Effect of misstatements on debt covenant compliance
(1, 'Misstatements and Control Deficiencies', 'Ridgemont Corporation has a debt covenant requiring a current ratio of at least 1.5:1. The auditor identifies uncorrected misstatements that, individually, are immaterial to the financial statements but collectively would reduce the current ratio from 1.52:1 to 1.47:1. The auditor should:', '["Ignore the misstatements since each one is individually immaterial", "Evaluate the misstatements as material due to their effect on covenant compliance", "Request management waive the covenant before issuing the report", "Disclose the misstatements in an emphasis-of-matter paragraph only"]'::jsonb, 1, 'AU-C 450.11 requires the auditor to evaluate whether uncorrected misstatements are material, individually or in the aggregate, considering the surrounding circumstances. Proximity to a debt covenant threshold is a qualitative factor that elevates otherwise immaterial amounts to material significance. Unlike ignoring individually immaterial items, the aggregate effect on compliance must be considered holistically.', 'medium', 2),

-- Q3: medium / L2 — Anomalous misstatement treatment
(1, 'Misstatements and Control Deficiencies', 'While auditing Pinecrest Manufacturing, the engagement team discovers a $12,000 misstatement in one sampled inventory item caused by a one-time data entry error during a system migration. No similar errors exist in the remaining sample. Under AU-C 530, the auditor should classify this as:', '["An anomalous misstatement that is not projected to the population", "A factual misstatement that requires full population testing", "A systematic error requiring expansion of the sample size", "A judgmental misstatement subject to management''s estimate revision"]'::jsonb, 0, 'AU-C 530.A18 states that a misstatement may be considered anomalous if the auditor can confirm it arises from a unique, non-recurring event and similar items in the population are not expected to contain similar errors. A one-time migration error meets this criterion. Unlike systematic errors, anomalous misstatements are not projected to the population because they are isolated events.', 'medium', 2),

-- Q4: medium / L3 — Segregation of duties deficiency evaluation
(1, 'Misstatements and Control Deficiencies', 'At Granite Peak Industries, the accounts payable clerk has the ability to create new vendors, enter invoices, and approve payments up to $10,000 without additional authorization. The company processes approximately $5 million in vendor payments annually. The auditor should evaluate this lack of segregation of duties as:', '["An inconsequential deficiency because the payment threshold limits exposure", "A control deficiency that does not rise to significant because it is monitored quarterly", "A significant deficiency because quarterly monitoring partially compensates for the risk", "A material weakness because a single individual could both create fictitious vendors and process payments"]'::jsonb, 3, 'AU-C 265.A7 indicates that inadequate segregation of duties that allows one individual to both initiate and process transactions creates a reasonable possibility that a material misstatement could occur and not be prevented or detected. The $10,000 threshold is irrelevant when the aggregate annual volume is $5 million. Unlike a significant deficiency, the absence of a preventive control over vendor creation and payment approval represents a material weakness.', 'medium', 3),

-- Q5: hard / L4 — Evaluating management bias in misstatement patterns
(1, 'Misstatements and Control Deficiencies', 'During the audit of Westfield Enterprises, the auditor observes that all eight uncorrected misstatements from the current year overstate revenue, each individually below performance materiality. In the prior two years, uncorrected misstatements similarly overstated revenue. The aggregate effect does not exceed materiality. The auditor should:', '["Accept the misstatements as immaterial since the aggregate falls below materiality", "Evaluate whether the pattern indicates management bias and consider the implications for fraud risk", "Require management to correct all current-year misstatements regardless of materiality", "Withdraw from the engagement due to evidence of intentional misstatement"]'::jsonb, 1, 'AU-C 450.A22 requires the auditor to consider whether uncorrected misstatements reflect a bias by management. A consistent directional pattern of revenue overstatement across multiple years—even when individually and aggregately immaterial—may indicate intentional bias requiring reassessment of fraud risk under AU-C 240. Unlike simply accepting the misstatements as immaterial, the auditor must evaluate the qualitative pattern rather than relying solely on quantitative thresholds.', 'hard', 4),

-- Q6: easy / L1 — Definition of a control deficiency
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, a control deficiency exists when:', '["Management intentionally overrides an established internal control", "The financial statements contain a material misstatement that was not detected", "A control is designed, implemented, or operated such that it is unable to prevent or detect misstatements on a timely basis", "The auditor is unable to obtain sufficient appropriate audit evidence about controls"]'::jsonb, 2, 'AU-C 265.06 defines a control deficiency as existing when the design or operation of a control does not allow management or employees, in the normal course of performing their assigned functions, to prevent or detect misstatements on a timely basis. Unlike management override, which is a separate fraud risk, a deficiency relates to the control''s inherent ability to function as intended.', 'easy', 1),

-- Q7: hard / L3 — Management override as indicator of material weakness
(1, 'Misstatements and Control Deficiencies', 'During the audit of Sterling Dynamics, the auditor discovers that the CFO repeatedly overrode the automated three-way match control to process $340,000 in payments to a vendor owned by a relative. The overrides were not logged or reviewed by anyone. The auditor should classify this situation as:', '["A material weakness because management override of controls without compensating review creates a reasonable possibility of material misstatement", "A significant deficiency because the override was performed by a senior officer with authority", "A control deficiency that does not require communication because management has override authority", "A fraud finding that should be reported to law enforcement before communicating to governance"]'::jsonb, 0, 'AU-C 265.A12 and AU-C 240.A36 indicate that management override without compensating controls—particularly where related-party transactions are involved—represents a material weakness. The absence of logging or independent review means no detective control exists to catch the override. Unlike a significant deficiency, the combination of override authority, related-party conflict, and absent monitoring creates a reasonable possibility of material misstatement going undetected.', 'hard', 3),

-- Q8: easy / L1 — Purpose of the summary of uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'What is the primary purpose of the auditor''s summary of uncorrected misstatements?', '["To serve as the basis for the auditor''s internal control opinion", "To document all errors for regulatory filing requirements", "To provide a record of corrections management must make before year-end", "To communicate identified misstatements that management has chosen not to correct"]'::jsonb, 3, 'AU-C 450.12 requires the auditor to communicate to those charged with governance all uncorrected misstatements and the effect they may have on the auditor''s opinion. The summary serves as the vehicle for this communication, ensuring transparency about management''s decision not to adjust. Unlike a list of required corrections, the summary documents what remains unadjusted so governance can make informed decisions.', 'easy', 1),

-- Q9: easy / L1 — What constitutes an uncorrected misstatement
(1, 'Misstatements and Control Deficiencies', 'Under auditing standards, an uncorrected misstatement is best described as:', '["Any error discovered after the audit report has been issued", "A misstatement identified during the audit that management has not corrected", "A misstatement the auditor chose not to investigate further", "An error in the prior period financial statements that was never restated"]'::jsonb, 1, 'AU-C 450.06 defines uncorrected misstatements as those accumulated by the auditor during the audit that have not been corrected. These are misstatements the auditor has identified and communicated but that management elected not to adjust. Unlike errors discovered after report issuance, uncorrected misstatements are known during the audit and evaluated before the opinion is formed.', 'easy', 1),

-- Q10: easy / L1 — Entity-level control deficiency concept
(1, 'Misstatements and Control Deficiencies', 'An entity-level control deficiency is best described as a weakness in:', '["The overall governance, risk management, or monitoring that affects the entire organization''s internal control system", "A specific transaction processing control within accounts payable", "The design of a single automated application control", "The physical security measures protecting a company''s data center"]'::jsonb, 0, 'AU-C 265.A8 recognizes that entity-level controls—such as the control environment, risk assessment process, and monitoring activities—operate broadly across an organization. Deficiencies at this level affect the reliability of controls throughout the entity, not just a single process. Unlike transaction-level deficiencies that affect specific accounts, entity-level weaknesses have pervasive implications for the financial statements.', 'easy', 1),

-- Q11: hard / L4 — Evaluating deficiency when compensating controls partially mitigate
(1, 'Misstatements and Control Deficiencies', 'Evergreen Health Systems lacks automated access controls over its billing system, allowing any billing clerk to modify patient charges without approval. Management argues that a monthly supervisory review of billing reports compensates for this weakness. The auditor notes the review is performed 30-45 days after transactions post and covers only summary-level data. The auditor should conclude that:', '["The compensating control fully mitigates the deficiency because management reviews the reports", "The compensating control reduces the deficiency to an inconsequential level requiring no communication", "The deficiency remains a material weakness because the detective control is neither timely nor detailed enough to prevent or detect misstatements", "The deficiency is a significant deficiency because some level of compensating control exists"]'::jsonb, 2, 'AU-C 265.A10 states that compensating controls must be evaluated for whether they actually achieve the objective of the deficient control. A summary-level review performed 30-45 days after posting is neither timely nor granular enough to detect individual unauthorized charge modifications. Unlike a significant deficiency where partial mitigation provides meaningful risk reduction, the compensating control here is insufficient to lower the severity from material weakness.', 'hard', 4),

-- Q12: medium / L2 — Previously communicated deficiency that persists
(1, 'Misstatements and Control Deficiencies', 'During the prior-year audit of Cascade Financial Group, the auditor communicated a significant deficiency related to inadequate review of journal entries. In the current year, the auditor finds that management has not remediated the deficiency. Under AU-C 265, the auditor should:', '["Omit the deficiency from the current communication since it was reported previously", "Reference only the prior-year communication without providing updated details", "Upgrade the deficiency to a material weakness because management failed to act", "Communicate the deficiency again in writing, noting it was previously reported"]'::jsonb, 3, 'AU-C 265.A17 states that if a previously communicated significant deficiency or material weakness remains unremediated, the auditor should communicate it again in the current period. Repetition is warranted because those charged with governance may have changed, and the persistence itself is relevant. Unlike upgrading to a material weakness, the mere failure to remediate does not automatically increase the severity classification.', 'medium', 2),

-- Q13: medium / L2 — Projected misstatement calculation in sampling
(1, 'Misstatements and Control Deficiencies', 'While auditing Lakeview Retail, the auditor tests a random sample of 60 accounts receivable confirmations from a population of 1,800 accounts totaling $2.7 million. The sample reveals $6,000 in overstatements across three accounts with a combined sampled balance of $90,000. The projected misstatement for the population is closest to:', '["$6,000", "$180,000", "$36,000", "$270,000"]'::jsonb, 1, 'AU-C 530.A19 requires projection of misstatements found in a sample to the entire population. The error rate is $6,000 / $90,000 = 6.67%, applied to the full population of $2.7 million yields $180,000. Unlike using the raw $6,000 amount, which is only the known misstatement in the sample, the projected misstatement estimates the likely total error by extrapolating the sample results to the untested population.', 'medium', 2),

-- Q14: medium / L3 — Reassessing audit approach after discovering significant misstatements
(1, 'Misstatements and Control Deficiencies', 'Midway through fieldwork at Northstar Logistics, the audit team discovers material misstatements in revenue recognition caused by a systematic failure to apply the company''s cutoff procedures. The auditor had initially assessed control risk over revenue as low. Under AU-C 315, the auditor should:', '["Reassess the risk of material misstatement and revise the audit plan to include additional substantive procedures", "Issue an adverse opinion based on the misstatements already identified", "Withdraw from the engagement because the initial risk assessment was incorrect", "Continue with the planned procedures since the misstatements were already detected"]'::jsonb, 0, 'AU-C 315.32 requires the auditor to revise the risk assessment when audit evidence contradicts the initial assessment. Discovery of systematic revenue cutoff failures indicates that control risk was underestimated, necessitating expanded substantive testing. Unlike continuing with planned procedures, the auditor must respond to the revised risk assessment with a modified audit approach under AU-C 330.', 'medium', 3),

-- Q15: easy / L1 — Three severity levels of control deficiencies
(1, 'Misstatements and Control Deficiencies', 'What are the three severity classifications for internal control deficiencies under auditing standards?', '["Minor deficiency, major deficiency, and critical deficiency", "Inconsequential deficiency, reportable condition, and material weakness", "Control deficiency, significant deficiency, and material weakness", "Design deficiency, operating deficiency, and systematic failure"]'::jsonb, 2, 'AU-C 265 establishes a hierarchy of three severity levels: control deficiency (the baseline), significant deficiency (a deficiency or combination important enough to merit governance attention), and material weakness (where a reasonable possibility exists that a material misstatement would not be prevented or detected). Unlike the outdated term "reportable condition," current standards use "significant deficiency."', 'easy', 1),

-- Q16: easy / L2 — Tolerable misstatement concept in audit sampling
(1, 'Misstatements and Control Deficiencies', 'During the planning phase for Mapleton Industries, the auditor sets performance materiality at $120,000 and determines the tolerable misstatement for the inventory account at $90,000. The tolerable misstatement represents:', '["The maximum misstatement the auditor will accept in the overall financial statements", "The amount below which all inventory misstatements are clearly trivial", "The threshold that triggers a qualified opinion for the inventory balance", "The maximum misstatement the auditor will accept in the inventory account while still concluding the financial statements are not materially misstated"]'::jsonb, 3, 'AU-C 530.05 defines tolerable misstatement as the application of performance materiality to a particular sampling procedure, representing the maximum error in a specific account the auditor can accept. Unlike overall materiality which applies to the financial statements as a whole, tolerable misstatement is set below performance materiality to allow for sampling risk and undetected errors in other accounts.', 'easy', 2),

-- Q17: hard / L4 — Evaluating net effect of misstatements that offset
(1, 'Misstatements and Control Deficiencies', 'During the audit of Redstone Energy, the auditor identifies a $175,000 overstatement in accounts receivable and a $160,000 understatement in accrued liabilities. Overall materiality is $250,000. Management argues the net effect of $15,000 on net income is clearly immaterial. The auditor should:', '["Accept management''s position because the net income effect is below materiality", "Evaluate the misstatements both individually by account and in the aggregate, considering that offsetting misstatements may mask the true magnitude of errors", "Require correction of only the larger misstatement since it exceeds performance materiality", "Report a scope limitation because the misstatements offset each other"]'::jsonb, 1, 'AU-C 450.A14 states that the auditor should evaluate misstatements individually and in the aggregate, and should not allow favorable misstatements to offset unfavorable ones when evaluating individual account balances. The $175,000 receivable overstatement may be material to that account even if the income statement effect is small. Unlike accepting the net effect, the auditor must consider whether each account balance is fairly stated.', 'hard', 4),

-- Q18: medium / L3 — Evaluating design vs. operating effectiveness deficiency
(1, 'Misstatements and Control Deficiencies', 'At Cedarwood Financial, the company designed a control requiring the controller to review and approve all journal entries over $50,000. Testing reveals the controller approves entries without examining supporting documentation, signing off within minutes of submission regardless of complexity. The auditor should classify this as:', '["A design deficiency because the threshold of $50,000 is set too high", "A monitoring deficiency because internal audit failed to detect the issue", "An operating effectiveness deficiency because the control exists as designed but is not performed effectively", "A significant deficiency only if a misstatement actually resulted from the inadequate review"]'::jsonb, 2, 'AU-C 265.A3 distinguishes between design deficiencies (control is missing or poorly designed) and operating deficiencies (control exists but is not performed effectively). The journal entry review control is properly designed but executed as a rubber stamp, making it an operating deficiency. Unlike a design deficiency where the control itself is flawed, here the control''s execution fails to achieve its intended objective.', 'medium', 3),

-- Q19: medium / L2 — Misstatement from incorrect accounting principle application
(1, 'Misstatements and Control Deficiencies', 'Thornfield Properties capitalizes all building maintenance costs exceeding $5,000 as leasehold improvements, including routine repairs such as repainting and replacing worn carpet. The auditor determines this practice misstates the financial statements by $230,000. Under AU-C 450, this is classified as:', '["A judgmental misstatement arising from management''s incorrect application of accounting principles to specific facts", "A projected misstatement based on the auditor''s sampling of maintenance invoices", "A factual misstatement requiring no further evaluation by the auditor", "A disclosure deficiency rather than a measurement misstatement"]'::jsonb, 0, 'AU-C 450.A3 identifies judgmental misstatements as differences arising from management''s judgments about accounting estimates or the selection and application of accounting policies that the auditor considers unreasonable. Capitalizing routine repairs violates ASC 360 and reflects incorrect policy application. Unlike factual misstatements where the amount is definitively known, judgmental misstatements involve management''s application of judgment to recognition or measurement.', 'medium', 2),

-- Q20: medium / L3 — Impact of identified misstatements on going concern evaluation
(1, 'Misstatements and Control Deficiencies', 'Valley Stream Corporation has a current ratio of 0.8:1 and has violated its primary credit facility covenant. During the audit, the engagement team identifies $400,000 in uncorrected misstatements that further reduce current assets. Overall materiality is $1 million. The auditor should consider whether these misstatements:', '["Are immaterial and therefore irrelevant to the going concern assessment", "Should trigger an immediate adverse opinion on the financial statements", "Require a disclaimer of opinion due to the uncertainty about the entity''s future", "Affect the auditor''s going concern evaluation even though they fall below materiality"]'::jsonb, 3, 'AU-C 570.A2 requires the auditor to consider all relevant information when evaluating going concern, including the effect of uncorrected misstatements. Even below-materiality misstatements can aggravate existing liquidity concerns and covenant violations. Unlike treating below-materiality items as irrelevant, the qualitative context of financial distress means these misstatements have heightened significance for the going concern assessment.', 'medium', 3),

-- Q21: medium / L3 — Evaluating deficiency when management corrective action is planned
(1, 'Misstatements and Control Deficiencies', 'During the audit of Summit Ridge Holdings, the auditor identifies a material weakness in the revenue recognition process. Management provides a detailed remediation plan with a target completion date six months after year-end. The auditor should:', '["Downgrade the finding to a significant deficiency because management has a remediation plan", "Communicate the material weakness based on the control''s effectiveness as of the reporting date, regardless of planned remediation", "Defer communication until management has had time to implement the corrective action", "Report the finding as a control deficiency since remediation is in progress"]'::jsonb, 1, 'AU-C 265.13 requires the auditor to evaluate and communicate control deficiencies based on their status as of the date being reported on. A planned remediation that has not yet been implemented does not change the current-year classification. Unlike downgrading based on future plans, the auditor must assess controls as they existed during the period under audit and communicate the material weakness accordingly.', 'medium', 3),

-- Q22: hard / L4 — Turnover in key financial reporting role as deficiency indicator
(1, 'Misstatements and Control Deficiencies', 'Apex Technologies experienced the departure of its controller and two senior accountants during the fiscal year. Temporary staff with limited industry knowledge filled these roles. The auditor identifies multiple misstatements in areas previously handled by the departed employees and notes that month-end close procedures were frequently delayed. The auditor should evaluate this situation as:', '["A potential material weakness because the loss of competent personnel and resulting misstatements indicate that controls dependent on those individuals failed to operate effectively", "A human resources issue outside the scope of internal control evaluation", "A significant deficiency only if the company fails to hire permanent replacements within 90 days", "An inherent limitation of internal control that requires no communication"]'::jsonb, 0, 'AU-C 265.A8 identifies competence of personnel as a component of the control environment. When personnel turnover leads to delayed close procedures and multiple misstatements, it indicates that person-dependent controls failed during the period. The combination of inadequate staffing, resulting misstatements, and process breakdowns satisfies the reasonable possibility threshold. Unlike treating turnover as merely a human resources issue, the auditor must assess its direct impact on financial reporting controls.', 'hard', 4),

-- Q23: easy / L1 — Written communication timing requirement
(1, 'Misstatements and Control Deficiencies', 'When must the auditor communicate significant deficiencies and material weaknesses in writing to those charged with governance?', '["Within 30 calendar days of discovery", "Before the entity files its annual report with the SEC", "Immediately upon identification during fieldwork", "No later than 60 days following the report release date"]'::jsonb, 3, 'AU-C 265.13 requires that written communication of significant deficiencies and material weaknesses be made no later than 60 days following the report release date. This timeline ensures governance receives the information while it is still actionable. Unlike requiring immediate communication during fieldwork, the standard provides a reasonable window after the audit report is released to finalize the written communication.', 'easy', 1),

-- Q24: easy / L1 — Management representation letter and misstatements
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 580, what representation should the auditor obtain from management regarding uncorrected misstatements?', '["That no misstatements exist in the financial statements", "That all misstatements were caused by employee error rather than fraud", "That management believes the effects of uncorrected misstatements are immaterial, individually and in the aggregate, to the financial statements as a whole", "That management will correct all identified misstatements before the next audit"]'::jsonb, 2, 'AU-C 580.A8 specifies that the auditor should request management to provide a written representation that it believes the effects of uncorrected misstatements aggregated during the audit are immaterial. A summary of these items is typically attached to the representation letter. Unlike stating that no misstatements exist, this representation acknowledges the identified items while asserting their immateriality.', 'easy', 1),

-- Q25: medium / L2 — Misstatement in disclosure vs. measurement
(1, 'Misstatements and Control Deficiencies', 'During the audit of Brookstone Pharmaceuticals, the auditor discovers that the company correctly measured its $8 million contingent liability but failed to disclose the nature of the underlying litigation, the possible range of loss, and the key assumptions in the notes to the financial statements. Under AU-C 450, this omission is classified as:', '["Not a misstatement because the liability amount is correctly measured", "A misstatement because it involves incomplete or misleading financial statement disclosures", "A scope limitation preventing the auditor from completing the engagement", "A deficiency in presentation that affects only the supplementary information"]'::jsonb, 1, 'AU-C 450.A1 defines misstatements as including omissions or inaccuracies in disclosures necessary for fair presentation. Even when amounts are correctly measured, inadequate note disclosures constitute misstatements under auditing standards. Unlike limiting the definition of misstatements to numerical errors, AU-C 450 encompasses qualitative omissions in the notes that affect users'' understanding of the financial statements.', 'medium', 2),

-- Q26: medium / L2 — Documentation requirements for misstatement evaluation
(1, 'Misstatements and Control Deficiencies', 'At Harborview Construction, the auditor identifies several misstatements during fieldwork, all of which management corrects. Under AU-C 450, the auditor''s documentation should include:', '["Only the uncorrected misstatements, since corrected items require no documentation", "A summary of all misstatements exceeding materiality that were communicated to governance", "The final adjusted financial statements without reference to the original misstatements", "All misstatements accumulated during the audit and the conclusion on whether uncorrected misstatements are material"]'::jsonb, 3, 'AU-C 450.14 requires the auditor to document the amount below which misstatements are clearly trivial, all misstatements accumulated during the audit (including those subsequently corrected), and the conclusion about whether uncorrected misstatements are material. Unlike documenting only uncorrected items, the auditor must maintain a complete record of all identified misstatements to support the overall evaluation.', 'medium', 2),

-- Q27: easy / L1 — Reasonable possibility threshold
(1, 'Misstatements and Control Deficiencies', 'In evaluating control deficiency severity, "reasonable possibility" under AU-C 265 means:', '["More than a remote likelihood that an event could occur", "Virtual certainty that a material misstatement will result", "A probability exceeding 50% that the deficiency will cause an error", "A quantitatively measured risk exceeding the tolerable misstatement amount"]'::jsonb, 0, 'AU-C 265.A11 clarifies that reasonable possibility is a threshold higher than remote but does not require it to be probable (i.e., likely to occur). This is the same threshold used in ASC 450 for contingency evaluation. Unlike requiring greater than 50% probability, the reasonable possibility threshold is met when the chance of occurrence is more than slight or inconsequential.', 'easy', 1),

-- Q28: medium / L3 — Identified control deficiency impact on substantive testing
(1, 'Misstatements and Control Deficiencies', 'The auditor of Fairmont Healthcare identifies a significant deficiency in the accounts payable authorization process during the interim testing phase. Planned substantive procedures for accounts payable consist of analytical procedures and limited detail testing. Under AU-C 330, the auditor should:', '["Maintain the planned procedures since the deficiency is only significant, not a material weakness", "Withdraw from performing substantive testing until the deficiency is corrected", "Modify the planned substantive procedures to address the increased risk of material misstatement in accounts payable", "Report the deficiency and defer any response to the subsequent audit period"]'::jsonb, 2, 'AU-C 330.07 requires the auditor to design and perform substantive procedures that are responsive to assessed risks of material misstatement. When a control deficiency increases the assessed risk for an account, the auditor must modify the nature, timing, or extent of substantive procedures accordingly. Unlike maintaining planned procedures, the identification of a significant deficiency signals that previously assessed control reliance was unwarranted.', 'medium', 3),

-- Q29: medium / L3 — Opening balance misstatements in initial engagement
(1, 'Misstatements and Control Deficiencies', 'Cedar Falls Corporation engages a new auditor for the fiscal year ending December 31, 2025. During opening balance procedures, the new auditor identifies a $150,000 misstatement in the prior-year ending inventory that was not detected by the predecessor auditor. Overall materiality for the current year is $500,000. The auditor should:', '["Ignore the prior-year misstatement since it was the predecessor''s responsibility", "Evaluate the effect of the misstatement on both the opening balances and the current-year financial statements", "Require management to restate the prior-year financial statements before continuing the audit", "Communicate the finding to the predecessor auditor and take no further action"]'::jsonb, 1, 'AU-C 510.09 requires the auditor to evaluate whether opening balances contain misstatements that materially affect the current-period financial statements. An inventory misstatement carries forward to cost of goods sold, directly affecting current-year income. Unlike ignoring the prior-year error, the new auditor must assess its current-year impact and determine whether a correction or modification of opinion is needed.', 'medium', 3),

-- Q30: hard / L4 — Evaluating pervasiveness of misstatement for opinion modification
(1, 'Misstatements and Control Deficiencies', 'Keystone Industries refuses to correct a $900,000 misstatement in its revenue recognition practices that overstates current-year revenue. The auditor determines the misstatement is material. Further analysis reveals the same recognition methodology affects accounts receivable, deferred revenue, and income tax provisions, and would cause misstatements in comparative prior-year amounts if restated. The auditor should evaluate this as:', '["A material misstatement confined to revenue requiring a qualified opinion", "A material misstatement that is not pervasive, warranting an emphasis-of-matter paragraph", "An immaterial misstatement given that it originated from a single accounting policy", "A material and pervasive misstatement because it affects multiple elements, accounts, and periods, warranting an adverse opinion"]'::jsonb, 3, 'AU-C 705.06 defines pervasive as effects that are not confined to specific elements, accounts, or items, or that represent a substantial proportion of the financial statements. A revenue misstatement cascading to receivables, deferred revenue, taxes, and prior-year comparatives meets the pervasiveness criterion. Unlike a qualified opinion for isolated material misstatements, the breadth of impact across accounts and periods supports an adverse opinion under AU-C 705.', 'hard', 4)
;

COMMIT;
